mapper.select:
 	select r.*,a.riskcatname,o.orgname as unitname from TBL_RISKEVENT r left join TBL_RISKCATEGORY a on r.riskcatid=a.riskcatid 
 	left join tbl_organization o on o.orgid=r.unit
 	where r.status = 6 and r.reportstatus=1  
 	and  r.riseveid in (
	select c.riseveid from (select riskeventcode,max(riseveid) 
             riseveid from TBL_RISKEVENT   group by riskeventcode) c  
      )
	${sql}

		and  RISKEVENTCODE    LIKE concat(concat('%',#{queryParam.riskeventcode}),'%')  



		AND RISKEVENTNAME LIKE concat(concat('%',#{queryParam.riskeventname}),'%')



		and OCCUREDDATE >=#{queryParam.startDate}



		and OCCUREDDATE <=#{queryParam.endDate}


		and r.unit=#{queryParam.unit}


		and r.recordorg=#{queryParam.recordorg}


	     and  r.recordorg in

	      #{item}	   



	     and  r.unit in

	      #{item}	   



				AND o.orgname LIKE concat(concat('%',#{queryParam.unitname}),'%')




		and losseventcategory=#{queryParam.losseventcategory}



	     and r.RISKCATID in

	      #{item}	   




	 order by riseveid desc

 select * from TBL_RISKEVENT where riseveid in (select c.riseveid from (select riskeventcode,max(riseveid) riseveid from TBL_RISKEVENT   group by riskeventcode) c  )  


	and RISKEVENTCODE LIKE concat(concat('%',#{queryParam.riskeventcode}),'%')  


	AND RISKEVENTNAME LIKE concat(concat('%',#{queryParam.riskeventname}),'%')


	and OCCUREDDATE >=#{queryParam.startDate}


	and OCCUREDDATE <=#{queryParam.endDate}


	    AND unit  = #{queryParam.unit}



	    AND losseventcategory  = #{queryParam.losseventcategory}


	    AND riseveid  in (${queryParam.ids})


     and RISKCATID in

      #{item}	   


     ${sql}
 order by riseveid desc

select * from TBL_RISKEVENT where status=6 and reportstatus=1

	and riseveid!=#{queryParam.riseveid}



	 		and RISKEVENTCODE = #{queryParam.riskeventcode}



	and ( 
	initialfatherriseveid =#{queryParam.initialfatherriseveid}
	or fatherriseveid =#{queryParam.initialfatherriseveid} 
	or riseveid =#{queryParam.initialfatherriseveid}
	)

order by riseveid desc

select * from TBL_RISKEVENT where  1=1

	and riseveid!=#{queryParam.riseveid}



	 		and RISKEVENTCODE = #{queryParam.riskeventcode}



	and ( 
	initialfatherriseveid =#{queryParam.initialfatherriseveid}
	or fatherriseveid =#{queryParam.initialfatherriseveid} 
	or riseveid =#{queryParam.initialfatherriseveid}
	)


    AND RISKFACTOR1  = #{queryParam.riskfactor1}

order by riseveid desc

select * from TBL_RISKEVENT where   status=6 and losseventcategory=2 and   (reportstatus is null or reportstatus ='' or reportstatus!=1) 


    AND RISKFACTOR1  = #{staffid}

order by riseveid desc

select case when losseventcategory=1 then '一般事件' else '重大事件' end AS name,count(1) as value from TBL_RISKEVENT where 1=1 and riseveid in (select c.riseveid from (select riskeventcode,max(riseveid) riseveid from TBL_RISKEVENT group by riskeventcode) c ) and status = 6 and reportstatus=1
and unit= #{company}
group by losseventcategory

	SELECT COUNT(1) FROM TBL_RISKEVENT WHERE 1=1 and  riseveid in (select c.riseveid from (select riskeventcode,max(riseveid) 
             riseveid from TBL_RISKEVENT   group by riskeventcode) c  )  and  status = 6 and reportstatus=1 

	  and losseventcategory=#{type}


	 and UNIT=#{orgid}


	 and year(createdate)=#{year}
